// Reset FineR1
FOR i := 1 TO 3 DO
    FineR1[i] := -1;
END_FOR;

// Calcolo FineR1 fino al primo 99
t := 0;
FOR i := 1 TO 3 DO
    codice := OrdineR1[i];
    IF codice = 99 THEN
        // Azzera gli elementi rimanenti (ignorati)
        FOR j := i TO 3 DO
            // Nulla da fare per FineR1, già inizializzati a -1
			FineR1[j] := FineR1[j]; // dummy operation per evitare errore sintattico
		END_FOR;
        EXIT;
    ELSIF codice >= 1 AND codice <= 3 THEN
        FineR1[codice] := t + DurataR1[i];
        t := t + DurataR1[i];
    END_IF;
END_FOR;

// Calcolo StartR2 fino al primo 99
t := 0;
FOR i := 1 TO 3 DO
    codice := OrdineR2[i];
    IF codice = 99 THEN
        // Ignora tutto ciò che viene dopo
        FOR j := i TO 3 DO
            StartR2[j] := -1;
        END_FOR;
        EXIT;
    ELSIF codice >= 1 AND codice <= 3 THEN
        StartR2[i] := t;
        t := t + DurataR2[i];
    ELSE
        StartR2[i] := -1;
    END_IF;
END_FOR;

// Calcolo Ritardi
FOR i := 1 TO 3 DO
    codice := OrdineR2[i];
    IF codice = 99 OR StartR2[i] = -1 THEN
        Ritardi[i] := -9999;
    ELSIF codice >= 1 AND codice <= 3 THEN
        IF FineR1[codice] >= 0 THEN
            Ritardi[i] := FineR1[codice] - StartR2[i];
        ELSE
            Ritardi[i] := 0;
        END_IF;
    ELSE
        Ritardi[i] := -9999;
    END_IF;
END_FOR;

// Calcolo T_Min
T_Min := 0;
FOR i := 1 TO 3 DO
    IF Ritardi[i] > T_Min THEN
        T_Min := Ritardi[i];
    END_IF;
END_FOR;

IF T_Min < 0 THEN
    T_Min := 0;
END_IF;

